import sys
from collections import deque

n = int(sys.stdin.read().split()[0])
moves = []
if n <= 6:
    # BFS over states; state[i] = peg (1..3) of disk i+1. The shortest solution is unique.
    start = tuple([1] * n)
    goal = tuple([3] * n)
    prev = {start: None}
    q = deque([start])
    while q:
        s = q.popleft()
        if s == goal:
            break
        for d in range(n):
            p = s[d]
            if any(s[e] == p for e in range(d)):
                continue  # disk d is not on top of its peg
            for t in (1, 2, 3):
                if t == p or any(s[e] == t for e in range(d)):
                    continue
                ns = s[:d] + (t,) + s[d + 1:]
                if ns not in prev:
                    prev[ns] = (s, p, t)
                    q.append(ns)
    cur = goal
    while prev[cur] is not None:
        s, p, t = prev[cur]
        moves.append(str(p) + ' ' + str(t))
        cur = s
    moves.reverse()
else:
    # iterative method: alternate between moving the smallest disk in a fixed cycle and the only other legal move
    pegs = {1: list(range(n, 0, -1)), 2: [], 3: []}
    cycle = [1, 3, 2] if n % 2 == 1 else [1, 2, 3]
    pos = 0
    total = 2 ** n - 1
    for step in range(total):
        if step % 2 == 0:
            a = cycle[pos]
            b = cycle[(pos + 1) % 3]
            pos = (pos + 1) % 3
        else:
            sm = cycle[pos]
            x, y = [p for p in (1, 2, 3) if p != sm]
            if not pegs[x]:
                a, b = y, x
            elif not pegs[y]:
                a, b = x, y
            elif pegs[x][-1] < pegs[y][-1]:
                a, b = x, y
            else:
                a, b = y, x
        pegs[b].append(pegs[a].pop())
        moves.append(str(a) + ' ' + str(b))
print(len(moves))
print('\n'.join(moves))

